; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: ti83 (TI-83 Plus / 84 Plus (TI-OS)), starts in normal mode
; ============================================================

			org #9D95

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)

ntc_start:
			di
			ld sp, ntc_ti_stack		; the platform's own real stack
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; main.bas 13: Input "How many passes (Return = 5)"; passes
			dw kw_printstrvar, str0
			dw kw_inputint, var_passes

			; main.bas 14: If passes < 1 Or passes > 100 Then passes = 5
			dw kw_scpltvl, var_passes, 1
			dw kw_ftov, tmp0
			dw kw_scpgtvl, var_passes, 100
			dw kw_ftov, tmp1
			dw kw_orvv, tmp0, tmp1, tmp0
			dw kw_goto_ifzero_n, tmp0, if1_1
			dw kw_ltov, 5, var_passes
if1_1:

			; main.bas 15: Do
do2_t:

			; main.bas 16: Print
			dw kw_printnl

			; main.bas 17: Print "T = turbo, N = normal, X = exit"
			dw kw_printstrvar, str1
			dw kw_printnl

			; main.bas 18: Do : k = UCase$(Inkey$) : Frame : Loop Until (k = "T") Or (k = "N") Or (k = "X")
do3_t:
			dw kw_inkeys, stmp0
			dw kw_strucase, var_k, stmp0
			dw kw_frame
			dw kw_strcmpeq, var_k, str2
			dw kw_ftov, tmp0
			dw kw_strcmpeq, var_k, str3
			dw kw_ftov, tmp1
			dw kw_orvv, tmp0, tmp1, tmp0
			dw kw_strcmpeq, var_k, str4
			dw kw_ftov, tmp1
			dw kw_orvv, tmp0, tmp1, tmp0
			dw kw_goto_ifzero_n, tmp0, do3_t
do3_e:

			; main.bas 19: If k = "X" Then Exit Do
			dw kw_strcmpeq, var_k, str4
			dw kw_goto_iffalse_n, if4_1
			dw do2_e_go
if4_1:

			; main.bas 20: Print IIf(k = "T", "Turbo", "Normal"); ": "; passes; " passes..."
			dw kw_strcmpeq, var_k, str2
			dw kw_ftov, tmp0
			dw kw_goto_ifzero_n, tmp0, ch5_0
			dw kw_strcpy, stmp0, str5
			dw ch5_e_go
ch5_0:
			dw kw_strcpy, stmp0, str6
			dw ch5_e_go
ch5_1:
			dw kw_strcpy, stmp0, str7
ch5_e:
			dw kw_printstrvar, stmp0
			dw kw_printstrvar, str8
			dw kw_printint, var_passes
			dw kw_printstrvar, str9
			dw kw_printnl

			; main.bas 21: t0 = Ticks
			dw kw_ticks, tmp0
			dw kw_vtov, tmp0, var_t0

			; main.bas 22: If k = "T" Then
			dw kw_strcmpeq, var_k, str2
			dw kw_goto_iffalse_n, if6_1

			; main.bas 23: Turbo On
			dw kw_turbo_on

			; main.bas 24: RunPasses
			dw p_runpasses_c

			; main.bas 25: Turbo Off
			dw kw_turbo_off

			; main.bas 26: Else
			dw if6_e_go
if6_1:

			; main.bas 27: RunPasses
			dw p_runpasses_n_c

			; main.bas 28: End If
if6_e:

			; main.bas 29: t1 = Ticks
			dw kw_ticks, tmp0
			dw kw_vtov, tmp0, var_t1

			; main.bas 30: Print "Done - stop the stopwatch"
			dw kw_printstrvar, str10
			dw kw_printnl

			; main.bas 31: Print cnt; " primes below "; TOP
			dw kw_printint, var_cnt
			dw kw_printstrvar, str11
			dw kw_printnl

			; main.bas 32: If (k = "N") And (System.TicksPerSecond > 0) Then
			dw kw_strcmpeq, var_k, str3
			dw kw_ftov, tmp0
			dw if7_1_go

			; main.bas 33: Print "took "; t1 - t0; " ticks = "; (t1 - t0) \ System.TicksPerSecond; "."; ((t1 - t0) Mod System.TicksPerSecond) * 10 \ System.TicksPerSecond; " s"

			; main.bas 34: ElseIf k = "T" Then
if7_1:
			dw kw_strcmpeq, var_k, str2
			dw kw_goto_iffalse_n, do2_t

			; main.bas 35: Print "(turbo runs with interrupts off, so"
			dw kw_printstrvar, str16
			dw kw_printnl

			; main.bas 36: Print "time it with the stopwatch)"
			dw kw_printstrvar, str17
			dw kw_printnl

			; main.bas 37: End If
if7_2:
if7_e:

			; main.bas 38: Loop
			dw do2_t_go
do2_e:

			; main.bas 39: End
			dw kw_printnl0
			dw kw_printstrvar, str18
			dw kw_waitkey
			dw kw_stop

